use runtime_bridge::service::*;
use std::{collections::VecDeque,sync::{Arc,atomic::{AtomicUsize,Ordering}},task::{Context,Poll,Waker},future::Future,time::Duration};
use tokio::sync::{Mutex,oneshot};
#[tokio::test] async fn increment_progress(){let s=Service::default();assert_eq!(tokio::time::timeout(Duration::from_secs(1),s.increment_and_snapshot()).await.unwrap(),1);assert_eq!(s.snapshot().await,1);}
#[tokio::test] async fn cancel_before_approval(){let q=Mutex::new(VecDeque::from([7]));let (_tx,rx)=oneshot::channel();let mut f=Box::pin(approved_pop(&q,rx));assert!(matches!(f.as_mut().poll(&mut Context::from_waker(Waker::noop())),Poll::Pending));drop(f);assert_eq!(*q.lock().await,VecDeque::from([7]));}
#[tokio::test] async fn closed_approval_preserves_queue(){let q=Mutex::new(VecDeque::from([7]));let (tx,rx)=oneshot::channel();drop(tx);assert_eq!(approved_pop(&q,rx).await,None);assert_eq!(*q.lock().await,VecDeque::from([7]));}
#[tokio::test] async fn cancel_after_approval_waiting_for_lock(){let q=Mutex::new(VecDeque::from([7]));let guard=q.lock().await;let(tx,rx)=oneshot::channel();tx.send(()).unwrap();let mut f=Box::pin(approved_pop(&q,rx));assert!(f.as_mut().poll(&mut Context::from_waker(Waker::noop())).is_pending());drop(f);drop(guard);assert_eq!(*q.lock().await,VecDeque::from([7]));}
struct Done(Arc<AtomicUsize>);impl Drop for Done{fn drop(&mut self){self.0.fetch_add(1,Ordering::SeqCst);}}
#[tokio::test] async fn stop_observes_destruction(){let count=Arc::new(AtomicUsize::new(0));let c=count.clone();let(tx,rx)=oneshot::channel();let worker=tokio::spawn(async move{let _d=Done(c);tx.send(()).unwrap();std::future::pending::<()>().await;});rx.await.unwrap();tokio::time::timeout(Duration::from_secs(1),stop_worker(worker)).await.unwrap();assert_eq!(count.load(Ordering::SeqCst),1);tokio::task::yield_now().await;assert_eq!(count.load(Ordering::SeqCst),1);}
#[tokio::test] async fn stop_waits_for_started_blocking_worker(){let (started_tx,started_rx)=oneshot::channel();let(release_tx,release_rx)=std::sync::mpsc::channel();let count=Arc::new(AtomicUsize::new(0));let c=count.clone();let worker=tokio::task::spawn_blocking(move||{started_tx.send(()).unwrap();release_rx.recv_timeout(Duration::from_secs(2)).unwrap();c.fetch_add(1,Ordering::SeqCst);});started_rx.await.unwrap();let mut stop=Box::pin(stop_worker(worker));assert!(stop.as_mut().poll(&mut Context::from_waker(Waker::noop())).is_pending());release_tx.send(()).unwrap();tokio::time::timeout(Duration::from_secs(1),stop).await.unwrap();assert_eq!(count.load(Ordering::SeqCst),1);}
